class RespError(Exception): pass

class RespParser:
    def __init__(self):
        self.buffer = b''
    def feed(self, data): self.buffer += data
    def _read_line(self):
        pos = self.buffer.find(b'\r\n')
        if pos == -1: return None, False
        line = self.buffer[:pos]
        self.buffer = self.buffer[pos+2:]
        return line, True
    def parse(self):
        line, ok = self._read_line()
        if not ok: return None
        prefix = line[:1]
        if prefix == b'+': return line[1:].decode('utf-8')
        elif prefix == b'-': return RespError(line[1:].decode('utf-8'))
        elif prefix == b':': return int(line[1:])
        elif prefix == b'$':
            length = int(line[1:])
            if length == -1: return None
            if len(self.buffer) < length + 2:
                self.buffer = line + b'\r\n' + self.buffer
                return None
            data = self.buffer[:length]
            self.buffer = self.buffer[length+2:]
            return data.decode('utf-8')
        else: return line.decode('utf-8')

def encode_bulk_string(s):
    return f'${len(s)}\r\n'.encode() + s + b'\r\n'
def encode_integer(n):
    return f':{n}\r\n'.encode()
def encode_simple_string(s):
    return f'+{s}\r\n'.encode()
def encode_error(s):
    return f'-{s}\r\n'.encode()

