import json, os, time

class RdbPersistence:
    def __init__(self, storage, fname='dump.rdb'):
        self.storage = storage; self.fname = fname
    def save(self):
        snap = {'data': {}, 'ts': time.time()}
        for k, v in self.storage.data.items():
            snap['data'][k] = str(v)
        tmp = self.fname + '.tmp'
        with open(tmp, 'w') as f: json.dump(snap, f)
        os.replace(tmp, self.fname)
        print(f'RDB saved: {self.fname}')
    def load(self):
        if not os.path.exists(self.fname): return
        with open(self.fname) as f: snap = json.load(f)
        for k, v in snap['data'].items():
            self.storage.data[k] = v
        print(f'RDB loaded: {len(snap["data"])} keys')

