from resp_parser import *

class ReplicationManager:
    def __init__(self, storage):
        self.storage = storage; self.role = 'master'
        self.replicas = []; self.repl_offset = 0
        self.backlog = b''; self.backlog_size = 1024*1024
    def propagate(self, parts):
        resp = encode_array(parts)
        self.backlog += resp
        if len(self.backlog) > self.backlog_size:
            self.backlog = self.backlog[-self.backlog_size:]
        for r in self.replicas:
            try: r.sendall(resp)
