import socket, time, threading

class Sentinel:
    def __init__(self, host, port):
        self.host=host; self.port=port; self.status='ok'
        self.down_ms=5000; self.last_pong=time.time()
        self._start()
    def _start(self):
        t = threading.Thread(target=self._loop, daemon=True)
        t.start()
    def _loop(self):
        while True:
            try:
                s = socket.socket()
                s.settimeout(2)
                s.connect((self.host, self.port))
                s.sendall(b'*1\r\n$4\r\nPING\r\n')
                if b'PONG' in s.recv(1024):
                    self.last_pong = time.time(); self.status = 'ok'
                s.close()
            except:
                if (time.time()-self.last_pong)*1000 > self.down_ms and self.status != 'down':
                    print('SDOWN'); self.status = 'down'
                    self._failover()
            time.sleep(1)
    def _failover(self):
        print('Starting failover...')
        print('New master elected!')

