import hashlib

def crc16(key):
    return int(hashlib.md5(key.encode()).hexdigest(), 16) % 16384

class ClusterManager:
    def __init__(self, node_id, host, port):
        self.node_id=node_id; self.host=host; self.port=port
        self.slot_map={}; self.my_slots=set()
    def add_slots(self, start, end):
        for s in range(start, end+1):
            self.slot_map[s]=self.node_id; self.my_slots.add(s)
    def get_slot(self, key):
        if '{' in key and '}' in key:
            a=key.index('{')+1; b=key.index('}')
            if b > a: key = key[a:b]
        return crc16(key) % 16384
    def route(self, key):
        slot = self.get_slot(key)
        owner = self.slot_map.get(slot)
        if owner == self.node_id: return {'action':'local'}
        elif owner: return {'action':'redirect','error':f'MOVED {slot} {owner}'}
        return {'action':'error','error':'CLUSTERDOWN'}

