from resp_parser import *
import fnmatch

class PubSubManager:
    def __init__(self):
        self.channels = {}; self.subscriptions = {}
    def subscribe(self, conn, ch):
        if ch not in self.channels: self.channels[ch]=set()
        self.channels[ch].add(conn)
        if conn not in self.subscriptions: self.subscriptions[conn]=set()
        self.subscriptions[conn].add(ch)
        return encode_array(['subscribe',ch,len(self.subscriptions[conn])])
    def publish(self, ch, msg):
        count = 0
        for c, subs in self.channels.items():
            if c != ch and not fnmatch.fnmatch(ch, c): continue
            for conn in list(subs):
                try:
                    conn.sendall(encode_array(['message',ch,msg]))
                    count += 1
                except: subs.discard(conn)
        return count
